import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import static org.junit.jupiter.api.Assertions.assertEquals;

class TitleRules {
    static boolean valid(String title) {
        return title != null && !title.isBlank();
    }
}

class TitleRulesTest {
    @ParameterizedTest
    @CsvSource({"Morning,true", "'   ',false", "'',false"})
    void titleNeedsVisibleText(String title, boolean expected) {
        assertEquals(expected, TitleRules.valid(title));
    }
}

import java.util.stream.Stream;
import org.junit.jupiter.api.extension.ExtensionContext;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.ArgumentsProvider;
import org.junit.jupiter.params.provider.ArgumentsSource;
import static org.junit.jupiter.api.Assertions.assertFalse;

class MissingTitles implements ArgumentsProvider {
    @Override
    public Stream<? extends Arguments> provideArguments(
            ExtensionContext context) {
        return Stream.of(Arguments.of((Object) null),
                         Arguments.of(""), Arguments.of(" "));
    }
}

class TitleRulesTest {
    @ParameterizedTest
    @ArgumentsSource(MissingTitles.class)
    void rejectsMissingOrBlankTitle(String title) {
        boolean valid = title != null && !title.isBlank();
        assertFalse(valid);
    }
}
